type Block struct {
	Index     int
	Timestamp string
	Hash      string
	PrevHash  string
	Nonce     int
	Transactions []Transaction
}

// HashBlock generates a SHA256 hash for a block
func HashBlock(block Block) string {
	hasher := sha256.New()
	hasher.Write([]byte(fmt.Sprintf("%d%s%s%d", block.Index, block.Timestamp, block.PrevHash, block.Nonce)))
	return hex.EncodeToString(hasher.Sum(nil))
}

// ProofOfWork generates a proof-of-work for a block
func ProofOfWork(block *Block, difficulty int) {
	target := big.NewInt(1)
	target.Lsh(target, 256-difficulty)

	for block.Hash[0:difficulty] != strings.Repeat("0", difficulty) {
		block.Nonce++
		block.Hash = HashBlock(*block)
	}
}

// Validate checks if the block's hash meets the difficulty criteria
func Validate(block Block, difficulty int) bool {
	return block.Hash[0:difficulty] == strings.Repeat("0", difficulty)
}

// Blockchain represents the chain of blocks
type Blockchain struct {
	Chain []Block
}

// AddBlock adds a new block to the blockchain
func (bc *Blockchain) AddBlock(block Block) {
	block.PrevHash = bc.Chain[len(bc.Chain)-1].Hash
	block.Hash = HashBlock(block)
